package com.smartblog.interceptor;
import com.fasterxml.jackson.databind.ObjectMapper; import com.smartblog.common.ApiResponse; import com.smartblog.entity.*; import com.smartblog.mapper.*; import com.smartblog.util.*; import com.smartblog.vo.CurrentUser; import jakarta.servlet.http.*; import org.springframework.stereotype.Component; import org.springframework.web.servlet.HandlerInterceptor;
@Component public class JwtAuthInterceptor implements HandlerInterceptor { private final JwtUtil jwtUtil; private final UserMapper userMapper; private final AuthSessionMapper sessionMapper; private final ObjectMapper objectMapper=new ObjectMapper(); public JwtAuthInterceptor(JwtUtil jwtUtil,UserMapper userMapper,AuthSessionMapper sessionMapper){this.jwtUtil=jwtUtil;this.userMapper=userMapper;this.sessionMapper=sessionMapper;} public boolean preHandle(HttpServletRequest request,HttpServletResponse response,Object handler) throws Exception{ if("OPTIONS".equalsIgnoreCase(request.getMethod())) return true; String h=request.getHeader("Authorization"); if(h==null||!h.startsWith("Bearer ")){writeUnauthorized(response,"未登录，请先登录"); return false;} String token=h.substring(7); if(!jwtUtil.validateToken(token)){writeUnauthorized(response,"Token 无效或已过期"); return false;} Long userId=jwtUtil.getUserId(token); String username=jwtUtil.getUsername(token); String sessionId=jwtUtil.getSessionId(token); String jti=jwtUtil.getJti(token); AuthSession s=sessionMapper.selectBySessionId(sessionId); if(s==null||s.getStatus()==null||s.getStatus()!=AuthConstants.SESSION_ACTIVE||s.getExpireTime().isBefore(java.time.LocalDateTime.now())){writeUnauthorized(response,"会话已失效，请重新登录"); return false;} if(!jti.equals(s.getAccessTokenJti())){writeUnauthorized(response,"登录状态已刷新，请重新请求"); return false;} User user=userMapper.selectById(userId); if(user==null||user.getStatus()==null||user.getStatus()!=AuthConstants.USER_ACTIVE){writeUnauthorized(response,"账号不可用，请重新登录"); return false;} UserContext.set(new CurrentUser(userId,username,sessionId)); return true;} public void afterCompletion(HttpServletRequest request,HttpServletResponse response,Object handler,Exception ex){UserContext.clear();} private void writeUnauthorized(HttpServletResponse response,String message) throws Exception{response.setContentType("application/json;charset=UTF-8"); response.setStatus(401); response.getWriter().write(objectMapper.writeValueAsString(ApiResponse.fail(401,message)));} }
